function prefixToInfix(s) {
  const isOp = (t) => t.length === 1 && "+-*/^".includes(t);
  const items = s.split("");                 // operators, operands and finished pieces
  while (items.length > 1) {
    for (let i = 0; i + 2 < items.length; i++) {
      // an operator followed by two finished operands is an innermost operation
      if (isOp(items[i]) && !isOp(items[i + 1]) && !isOp(items[i + 2])) {
        items.splice(i, 3, "(" + items[i + 1] + items[i] + items[i + 2] + ")");
        break;                               // the list changed: start over
      }
    }
  }
  return items[0];
}

