string build(const string& s, int& i) {
    char c = s[i++];
    if (string("+-*/^").find(c) == string::npos) return string(1, c);   // an operand is complete on its own
    string left = build(s, i);               // the operator's first operand...
    string right = build(s, i);              // ...then its second
    return "(" + left + c + right + ")";
}

