function prefixToInfix(s) {
  const stack = [];
  for (let i = s.length - 1; i >= 0; i--) {     // read right to left
    const c = s[i];
    if ("+-*/^".includes(c)) {
      const left = stack.pop();
      const right = stack.pop();
      stack.push("(" + left + c + right + ")");
    } else {
      stack.push(c);                              // an operand
    }
  }
  return stack.pop();
}

def prefix_to_infix(s):
    stack = []
    for c in reversed(s):                         # read right to left
        if c in "+-*/^":
            left = stack.pop()
            right = stack.pop()
            stack.append("(" + left + c + right + ")")
        else:
            stack.append(c)                       # an operand
    return stack.pop()

