string prefixToInfix(const string& s) {
    stack<string> st;
    for (int i = (int)s.size() - 1; i >= 0; i--) {   // read right to left
        char c = s[i];
        if (string("+-*/^").find(c) != string::npos) {
            string left = st.top(); st.pop();
            string right = st.top(); st.pop();
            st.push("(" + left + c + right + ")");
        } else {
            st.push(string(1, c));                   // an operand
        }
    }
    return st.top();
}
